begin;
create schema rincon_test;
grant usage on schema rincon_test to anon,authenticated,service_role;
create function rincon_test.assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERT: %',msg;end if;end$$;
create function rincon_test.denied(command text) returns void language plpgsql as $$begin begin execute command;exception when others then return;end;raise exception 'Expected denial: %',command;end$$;
grant execute on all functions in schema rincon_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('10000000-0000-0000-0000-000000000001','absent@test.invalid'),('10000000-0000-0000-0000-000000000002','attended@test.invalid'),('10000000-0000-0000-0000-000000000003','unlinked@test.invalid');
insert into public.players(id,name,number,active) values('rincon-absent','Ausente',91,true),('rincon-present','Presente',92,true),('rincon-other','Otro',93,true);
insert into private.team_accounts values('10000000-0000-0000-0000-000000000001','rincon-absent'),('10000000-0000-0000-0000-000000000002','rincon-present');
insert into public.league_snapshots(id,data) values('rincon-test','{"matches":[{"key":"rincon:played","home":"LAST DANCE","away":"OTHER","status":"played"}]}');
insert into public.published_reports(match_key,entries) values('rincon:played','[{"playerId":"rincon-present","goals":0,"assists":0,"yellow":0,"red":0}]');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select public.rincon_notices('subscribe','{"endpoint":"https://fcm.googleapis.com/fcm/send/test-device","p256dh":"BAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","auth":"AAAAAAAAAAAAAAAAAAAAAA"}');
select public.rincon_notices('settings','{"tutorial_dismissed":true}');
select rincon_test.assert((public.rincon_notices()->>'tutorial_dismissed')::boolean,'dismissal persists');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.save_rincon_comment('rincon:played','rincon-present','@Presente#92 vaya partido 😂','[{"player_id":"rincon-present","label":"@Presente#92"}]');
select rincon_test.assert((public.rincon_comments_page('rincon:played')->'viewer'->>'can_write')::boolean,'absent player can comment');
select public.react_rincon_comment((public.rincon_comments_page('rincon:played')->'items'->0->>'id')::uuid,'😂');
select public.react_rincon_comment((public.rincon_comments_page('rincon:played')->'items'->0->>'id')::uuid,'🔥');
select rincon_test.assert(public.rincon_comments_page('rincon:played')->'items'->0->'reactions'->0->>'emoji'='🔥','reaction changes without duplicating');
select public.react_rincon_comment((public.rincon_comments_page('rincon:played')->'items'->0->>'id')::uuid,null);
select rincon_test.assert(public.rincon_comments_page('rincon:played')->'items'->0->'reactions'='[]'::jsonb,'reaction removed');
select public.save_rincon_comment('rincon:played','rincon-present','@Presente#92 editado','[{"player_id":"rincon-present","label":"@Presente#92"}]');
select rincon_test.denied($q$select public.save_rincon_comment('rincon:played','rincon-absent','No fue')$q$);
select rincon_test.denied($q$select public.save_rincon_comment('rincon:played','rincon-present','Falso','[{"player_id":"rincon-present","label":"@Presente#92"}]')$q$);
select rincon_test.denied($q$select public.rincon_dispatch('claim')$q$);
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select rincon_test.assert((public.rincon_notices()->>'unread')::int=1,'mention arrives exactly once after edit');
select public.rincon_notices('read');
select rincon_test.assert((public.rincon_notices()->>'unread')::int=0,'mark read');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select rincon_test.denied($q$select public.rincon_notices()$q$);
select rincon_test.denied($q$select public.react_rincon_comment(gen_random_uuid(),'😂')$q$);
reset role;
select rincon_test.assert((select count(*) from private.rincon_notifications where user_id='10000000-0000-0000-0000-000000000002')=1,'one internal notification');
set local role service_role;
select rincon_test.assert(public.rincon_dispatch('claim')='[]'::jsonb,'read notification is not pushed');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.save_rincon_comment('rincon:played','rincon-present','Sin mención','[]');
select public.save_rincon_comment('rincon:played','rincon-present','@Presente#92 otra vez','[{"player_id":"rincon-present","label":"@Presente#92"}]');
reset role;
select rincon_test.assert((select count(*) from private.rincon_notifications where user_id='10000000-0000-0000-0000-000000000002')=0,'remove and readd does not re-notify');
set local role anon;
select rincon_test.denied($q$select public.rincon_notices()$q$);
select rincon_test.denied($q$select * from private.push_subscriptions$q$);
select rincon_test.assert(jsonb_array_length(public.rincon_comments_page('rincon:played')->'items')=1,'public comments preserved');
rollback;
